/**
 * VS Code settings for /session slash-command summarization.
 *
 * Summaries are generated by responses-vllm-proxy POST /v1/summarize-session,
 * which forwards to the configured vLLM backend (see proxy config.yaml). When
 * that call fails, the extension retries against the OpenAI-compatible
 * fallback endpoint configured via acp.sessionSummary.fallbackEndpoint
 * (recommended: DeepSeek's official API, https://api.deepseek.com — verified
 * OpenAI-compatible, POST /v1/chat/completions). No endpoint is hard-coded;
 * the fallback stays disabled until the user configures one plus a key.
 */
import * as vscode from 'vscode';

export interface SessionSummarySettings {
  /** vLLM proxy base URL (no trailing slash), e.g. http://127.0.0.1:8317 */
  endpoint: string;
  /** Optional Bearer token when the proxy has api-keys configured. */
  apiKey: string;
  timeoutMs: number;
  /** Model alias to use for summarization (resolved by the proxy). Empty = auto-select. */
  model: string;
  /** OpenAI-compatible fallback base URL, e.g. https://api.deepseek.com. Empty = fallback disabled. */
  fallbackEndpoint: string;
  /** Bearer token for the fallback API (DeepSeek API key). Empty = fallback disabled. */
  fallbackApiKey: string;
  /** Fallback model id, e.g. deepseek-v4-flash (DeepSeek-V4-Flash-0731). */
  fallbackModel: string;
}

const DEFAULT_ENDPOINT = 'http://127.0.0.1:8317';
const DEFAULT_MODEL = 'qwen38-27b';
/** No baked-in fallback URL — configured per-install via acp.sessionSummary.fallbackEndpoint. */
const DEFAULT_FALLBACK_ENDPOINT = '';
const DEFAULT_FALLBACK_MODEL = 'deepseek-v4-flash';

export function readSessionSummarySettings(): SessionSummarySettings {
  const cfg = vscode.workspace.getConfiguration('acp');
  return {
    endpoint: (cfg.get<string>('sessionSummary.endpoint') || DEFAULT_ENDPOINT).replace(/\/+$/, ''),
    apiKey: (cfg.get<string>('sessionSummary.apiKey') || '').trim(),
    timeoutMs: Math.max(5000, cfg.get<number>('sessionSummary.timeoutMs') ?? 120_000),
    model: (cfg.get<string>('sessionSummary.model') || DEFAULT_MODEL).trim(),
    fallbackEndpoint: (cfg.get<string>('sessionSummary.fallbackEndpoint') || DEFAULT_FALLBACK_ENDPOINT).replace(
      /\/+$/,
      '',
    ),
    fallbackApiKey: (cfg.get<string>('sessionSummary.fallbackApiKey') || '').trim(),
    fallbackModel: (cfg.get<string>('sessionSummary.fallbackModel') || DEFAULT_FALLBACK_MODEL).trim(),
  };
}

/** Full URL for POST /v1/summarize-session on the vLLM proxy. */
export function buildSummarizeSessionUrl(endpoint: string = readSessionSummarySettings().endpoint): string {
  return `${endpoint.replace(/\/+$/, '')}/v1/summarize-session`;
}
